import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define K_PER_BLOCK 2048
#define TILE_K 256
__global__ void matmul_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int N, int K) {
    extern __shared__ float As[];
    int m = blockIdx.x;
    int n = threadIdx.x;
    if (n >= N) return;
    int k_start = blockIdx.y * K_PER_BLOCK;
    int k_end = k_start + K_PER_BLOCK;
    if (k_end > K) k_end = K;
    const float* A_row = A + (size_t)m * K;
    float sum = 0.0f;
    // Cooperative staging of A into shared memory: A_row[k] is identical
    // for every thread (n) in this block, so loading it once per block
    // and reusing it via shared memory removes redundant global loads
    // that were previously repeated N times per element.
    for (int kb = k_start; kb < k_end; kb += TILE_K) {
        int tile_len = k_end - kb;
        if (tile_len > TILE_K) tile_len = TILE_K;
        for (int i = threadIdx.x; i < tile_len; i += blockDim.x) {
            As[i] = A_row[kb + i];
        }
        __syncthreads();
        int i = 0;
        int unroll_end = (tile_len / 4) * 4;
        #pragma unroll 4
        for (; i < unroll_end; i += 4) {
            float a0 = As[i];
            float a1 = As[i + 1];
            float a2 = As[i + 2];
            float a3 = As[i + 3];
            float b0 = B[(size_t)(kb + i) * N + n];
            float b1 = B[(size_t)(kb + i + 1) * N + n];
            float b2 = B[(size_t)(kb + i + 2) * N + n];
            float b3 = B[(size_t)(kb + i + 3) * N + n];
            sum += a0 * b0 + a1 * b1 + a2 * b2 + a3 * b3;
        }
        for (; i < tile_len; ++i) {
            sum += As[i] * B[(size_t)(kb + i) * N + n];
        }
        __syncthreads();
    }
    atomicAdd(&C[(size_t)m * N + n], sum);
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");

    A = A.contiguous();
    B = B.contiguous();

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    int k_blocks = (K + K_PER_BLOCK - 1) / K_PER_BLOCK;

    dim3 grid(M, k_blocks);
    dim3 block(N);

    matmul_kernel<<<grid, block, TILE_K * sizeof(float)>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}
"""
matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) with a large K dimension
    using a custom CUDA kernel that splits the K dimension across blocks and accumulates
    results via atomicAdd, with coalesced memory access patterns for B.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_cuda = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matmul_cuda.matmul_cuda(A, B)


M = 256
N = 256
K = 131072 * 4


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, N)
    return [A, B]


